begin;
select plan(7);
select ok((select count(*)=10 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('service_role',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('list_schedule_snapshots','read_schedule_snapshot','mutate_schedule_snapshot','check_schedule_snapshot_request','expire_schedule_snapshots','read_snapshot_policy','save_snapshot_policy','review_snapshot_copy','copy_schedule_snapshot','check_snapshot_copy')), 'Snapshot entrypoints require authenticated calls');
select ok((select bool_and(not has_table_privilege(r.name,t.name,'SELECT,INSERT,UPDATE,DELETE')) from (values('private.schedule_snapshots'),('private.schedule_snapshot_policy'),('private.schedule_snapshot_receipts'),('private.schedule_snapshot_policy_receipts'),('private.schedule_snapshot_imports'),('private.schedule_snapshot_copy_receipts')) t(name) cross join (values('anon'),('authenticated'),('service_role')) r(name)), 'No client bypass of snapshot content, policies, provenance, or receipts');
select ok((select count(*)=6 and bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('schedule_snapshots','schedule_snapshot_policy','schedule_snapshot_receipts','schedule_snapshot_policy_receipts','schedule_snapshot_imports','schedule_snapshot_copy_receipts')), 'All snapshot private tables retain RLS');
select ok(not has_function_privilege('authenticated','private.materialize_snapshot_collection(uuid)','EXECUTE') and not has_function_privilege('service_role','private.materialize_snapshot_collection(uuid)','EXECUTE'), 'Catalogue materialization is trusted-importer only');
select ok(not has_function_privilege('authenticated','private.snapshot_actor_can(uuid,uuid,text)','EXECUTE'), 'Snapshot permission helper is private');
select ok((select count(*)=10 and bool_and(p.prosecdef and 'search_path=""'=any(p.proconfig)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('list_schedule_snapshots','read_schedule_snapshot','mutate_schedule_snapshot','check_schedule_snapshot_request','expire_schedule_snapshots','read_snapshot_policy','save_snapshot_policy','review_snapshot_copy','copy_schedule_snapshot','check_snapshot_copy')), 'Snapshot definer routines pin an empty search path');
select ok(not exists(select 1 from pg_constraint where contype='f' and conrelid in ('private.schedule_snapshot_imports'::regclass,'private.schedule_snapshot_receipts'::regclass,'private.schedule_snapshot_copy_receipts'::regclass) and confrelid='private.schedule_snapshots'::regclass), 'Purge cannot cascade through independently retained import/copy receipts');
select * from finish();rollback;
